tests.code:
const fn = new Function(code + "\nreturn { debounce };");
const { debounce } = fn();
let calls = 0;
const tick = () => calls++;
const clock = { now: () => t };
let t = 0;
const d = debounce(tick, 100, clock);
d(); t = 50; d(); t = 90; d();
t = 95;
if (calls !== 0) throw new Error("No quiet gap yet — tick must not have run.");
t = 200; d(); t = 310;
if (calls !== 1) throw new Error("After a 110ms gap the trailing call ran exactly once.");

const fn = new Function(code + "\nreturn { throttle };");
const { throttle } = fn();
let calls = 0;
const tick = () => calls++;
const clock = { now: () => t };
let t = 0;
const th = throttle(tick, 100, clock);
th();
if (calls !== 1) throw new Error("Leading edge: first call runs immediately.");
t = 50; th(); t = 99; th();
if (calls !== 1) throw new Error("Within the window, blocked.");
t = 150; th();
if (calls !== 2) throw new Error("Window elapsed => runs again.");
